import type { ActorContext, EmployeeId } from '@maoeh/shared-types';
import type { LlmGateway } from '@maoeh/llm-gateway';
import { createCallBudget } from '@maoeh/llm-gateway';

/**
 * 一鱼多吃 · real multi-platform copy generation.
 *
 * The console already delivered "multi-platform content boards", but the board generated its
 * copy with a client-side function that returned four fixed strings with the brief spliced in.
 * That is a template wearing a product's clothes: the platforms differ only in which literal was
 * returned, and nothing was generated by a model.
 *
 * This service is the real path. One source material in, one prompt per platform out — each with
 * that platform's own format contract (length, structure, hook, tags) — and the model's answer
 * returned as-is. The provenance of every asset travels with it (`mode`, `provider`, `model`), so
 * a page can say "generated by deepseek-flash" instead of implying it. If the runtime is in mock
 * mode the assets are labelled `mock` — never presented as model output.
 *
 * It is deliberately *not* an agent cognition path: this is a tool the operator invokes, it writes
 * no events, and it therefore has no workflow semantics to get wrong. The LLM call is still
 * attributable (it carries the founder's actor context) and still counted by the gateway, so
 * `/api/llm` reflects it.
 */

export const CONTENT_PLATFORMS = ['xiaohongshu', 'douyin', 'bilibili', 'wechat'] as const;
export type ContentPlatform = (typeof CONTENT_PLATFORMS)[number];

export interface PlatformBrief {
  readonly id: ContentPlatform;
  readonly name: string;
  readonly kind: string;
  /** What this platform's native format actually is — the instruction that makes outputs differ. */
  readonly guide: string;
}

export const PLATFORM_BRIEFS: Readonly<Record<ContentPlatform, PlatformBrief>> = Object.freeze({
  xiaohongshu: {
    id: 'xiaohongshu',
    name: '小红书',
    kind: '图文笔记',
    guide:
      '小红书种草笔记：一个带情绪的标题，正文 200-350 字，用 emoji 分隔出 3-5 个可执行要点，'
      + '结尾一句互动引导，再加 3-6 个话题标签（#开头）。语气亲近、第一人称、口语化。',
  },
  douyin: {
    id: 'douyin',
    name: '抖音',
    kind: '口播脚本',
    guide:
      '抖音 30 秒口播脚本：前 3 秒必须是钩子（提问/反常识/结果前置），随后 2-3 个分镜提示（画面 + 台词），'
      + '总字数 150-250 字，结尾一句明确的行动号召。不要写成分点论文。',
  },
  bilibili: {
    id: 'bilibili',
    name: 'B站',
    kind: '视频脚本',
    guide:
      'B站视频脚本：一个信息量大的标题，正文 300-500 字，用「0:00 / 0:30」这样的章节时间轴组织，'
      + '每个章节一句干货结论，结尾自然引导三连（点赞/投币/收藏）。语气理性、可以自嘲。',
  },
  wechat: {
    id: 'wechat',
    name: '公众号',
    kind: '推文',
    guide:
      '公众号推文：先给 3 个备选标题，正文 400-600 字，用一句金句开头，'
      + '分 2-3 个小标题展开，结尾一个转发/留言引导。语气克制、可信、有信息密度。',
  },
});

export interface ContentAsset {
  readonly platform: ContentPlatform;
  readonly name: string;
  readonly kind: string;
  readonly text: string;
}

export type ContentProvenance = 'live' | 'mock';

export interface ContentStudioResult {
  readonly provenance: ContentProvenance;
  readonly provider: string | null;
  readonly model: string | null;
  readonly source: string;
  readonly assets: readonly ContentAsset[];
  /** How many model calls this generation actually made (one per platform). */
  readonly calls: number;
}

export interface ContentStudioInput {
  readonly source: string;
  readonly platforms?: readonly string[];
}

export class ContentStudioError extends Error {
  constructor(
    readonly code: 'invalid' | 'provider',
    message: string,
  ) {
    super(message);
    this.name = 'ContentStudioError';
  }
}

const MAX_SOURCE_CHARS = 20_000;

export interface ContentStudioDeps {
  readonly gateway: LlmGateway;
  /** `mock` answers from the deterministic provider; the label is what keeps it honest. */
  readonly provenance: ContentProvenance;
  readonly provider: string | null;
  readonly model: string | null;
  /** The seat the generation is attributed to (the founder's CEO seat). */
  readonly actorContext: ActorContext;
  /** Per-request correlation, so two generations are distinguishable in the LLM ledger. */
  readonly correlationId?: () => string;
  readonly employeeId?: EmployeeId;
}

export interface ContentStudio {
  generate(input: ContentStudioInput): Promise<ContentStudioResult>;
}

function platformList(requested: readonly string[] | undefined): readonly PlatformBrief[] {
  const ids = requested === undefined || requested.length === 0
    ? [...CONTENT_PLATFORMS]
    : requested;
  const briefs: PlatformBrief[] = [];
  for (const id of ids) {
    const brief = PLATFORM_BRIEFS[id as ContentPlatform];
    if (brief === undefined) {
      throw new ContentStudioError('invalid', `unknown platform "${id}"`);
    }
    if (!briefs.some((entry) => entry.id === brief.id)) briefs.push(brief);
  }
  return briefs;
}

const SYSTEM_PROMPT = [
  'You write platform-native marketing copy for a small content team.',
  'Follow the platform brief exactly: length, structure and tone are part of the deliverable.',
  'Write in the same language as the source material.',
  'Output only the copy that will be published, with no preface, commentary, markdown fences or translation notes.',
].join(' ');

function promptFor(brief: PlatformBrief, source: string): string {
  return [
    `Platform: ${brief.name} (${brief.kind})`,
    `Format contract: ${brief.guide}`,
    '',
    'Source material:',
    source,
    '',
    `Now write the ${brief.name} version. It must read as if a human wrote it for ${brief.name} specifically — not as a generic caption.`,
  ].join('\n');
}

export function createContentStudio(deps: ContentStudioDeps): ContentStudio {
  let sequence = 0;
  const nextId = deps.correlationId ?? (() => `content-studio-${String((sequence += 1))}`);

  return {
    async generate(input: ContentStudioInput): Promise<ContentStudioResult> {
      const source = input.source.trim();
      if (source === '') throw new ContentStudioError('invalid', 'source must not be empty');
      if (source.length > MAX_SOURCE_CHARS) {
        throw new ContentStudioError(
          'invalid',
          `source must be at most ${String(MAX_SOURCE_CHARS)} characters`,
        );
      }
      const briefs = platformList(input.platforms);
      const budget = createCallBudget(briefs.length);
      const assets: ContentAsset[] = [];
      let calls = 0;

      for (const brief of briefs) {
        const correlationId = nextId();
        const result = await deps.gateway.generate({
          actorContext: { ...deps.actorContext, correlationId: correlationId as never },
          request: {
            requestId: `content-${brief.id}-${correlationId}`,
            system: SYSTEM_PROMPT,
            prompt: promptFor(brief, source),
            responseFormat: 'text',
            temperature: 0.8,
            ...(deps.provider === null ? {} : { provider: deps.provider }),
            ...(deps.model === null ? {} : { model: deps.model }),
          },
          budget,
        });
        calls += 1;
        if (!result.ok) {
          throw new ContentStudioError(
            'provider',
            `platform "${brief.id}" generation failed: ${result.error.code}`,
          );
        }
        const text = result.value.text.trim();
        if (text === '') {
          throw new ContentStudioError('provider', `platform "${brief.id}" returned no text`);
        }
        assets.push({ platform: brief.id, name: brief.name, kind: brief.kind, text });
      }

      return {
        provenance: deps.provenance,
        provider: deps.provider,
        model: deps.model,
        source,
        assets,
        calls,
      };
    },
  };
}
